/**
 * Checkbox. Off, it is a recessed well — a hole in
 * the chassis, like the radio's. On, it becomes the lit primary cap with a
 * tick: the SAME primary-cap stops and cream legend as the Record button, so
 * "the accent" is one accent across the library (and a pairing the material tests
 * already hold to contrast). No outer glow. Composes var(--echo-*).
 */
.echo-checkbox {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: var(--echo-radius-sm);
  cursor: pointer;
  background: var(--echo-drawn-hollow, linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  ));
  /* Bezel: a 1px rim of chassis plastic, so the hole reads on any ground. */
  /* useCapPhysics sets --press (0 → 1 as it lands): the hole deepens and the
     lit cap's drop closes up. It owns the transform, so none is set here. */
  box-shadow:
    inset 0 calc(2px + 1px * var(--press, 0)) calc(4px + 2px * var(--press, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.06 * var(--echo-gloss, 1))),
    0 0 0 1px color-mix(in oklab, var(--echo-cap) 85%, transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  transition: background var(--echo-duration-swap) ease;
}

.echo-checkbox[data-checked],
.echo-checkbox[data-indeterminate] {
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.45 * var(--echo-gloss, 1))),
    inset 0 -2px 3px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.3 * var(--echo-shade, 1) * 100%), transparent),
    0 calc(1px - 1px * var(--press, 0)) calc(2px - 1px * var(--press, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-checkbox:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}

.echo-checkbox:disabled {
  opacity: 0.45;
  cursor: default;
}

.echo-checkbox__indicator {
  display: inline-flex;
  /* The primary cap's own legend colour (see hardware-button.css). */
  color: var(--echo-primary-cap-ink, var(--echo-text));
}
.echo-checkbox__indicator svg {
  width: var(--echo-icon-sm, 14px);
  height: var(--echo-icon-sm, 14px);
}
.echo-checkbox__dash,
.echo-checkbox[data-indeterminate] .echo-checkbox__check {
  display: none;
}
.echo-checkbox[data-indeterminate] .echo-checkbox__dash {
  display: block;
}

@media (prefers-reduced-motion: reduce) {
  .echo-checkbox {
    transition: none;
  }
}

/*
 * WCAG 2.2 2.5.8 — a target must be at least 24x24 CSS px.
 *
 * Expanded with a centred pseudo-element rather than by growing the control:
 * the visual size IS the design, and no component in the library used hit-area
 * expansion before this, so every target was exactly as big as it looked.
 * `max(100%, 24px)` keeps the expansion a floor — a target already larger than
 * 24px is untouched.
 */
.echo-checkbox {
  position: relative;
  /* Declares a deliberate 24px target pad; see tests/helpers/layout.ts. */
  --echo-hit-area: 24px;
}

.echo-checkbox::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: max(100%, 24px);
  height: max(100%, 24px);
  transform: translate(-50%, -50%);
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the 44px both
 * platform guidelines use — a fingertip rather than conformance. Gated on
 * `@media (pointer: coarse)`, so the desktop rendering does not move.
 *
 * Where a control's visual size is the design (a 24px checkbox, a 10px pip),
 * the target is grown with the same transparent pseudo-element as the 24px minimum,
 * not by growing the control.
 */
@media (pointer: coarse) {
  .echo-checkbox {
    --echo-hit-area: 44px;
  }

  .echo-checkbox::after {
    width: max(100%, 44px);
    height: max(100%, 44px);
  }
}

/*
 * Forced colors (Windows High Contrast) drops the box's gradient and shadows,
 * so an unchecked checkbox disappeared entirely. System colors draw the box
 * and the checked state; nothing here disables forced colors, so focus shows.
 */
@media (forced-colors: active) {
  .echo-checkbox {
    border: var(--echo-border-thick, 2px) solid ButtonText;
  }
  .echo-checkbox[data-checked],
  .echo-checkbox[data-indeterminate] {
    border-color: Highlight;
    color: Highlight;
  }
}

"use client";

/**
 * Checkbox. Base UI Checkbox behavior with a
 * molded box skin and a select sound on change.
 *
 * It presses like the library's keys (useCapPhysics): it resists, gives and
 * lands, sinks further while held, and comes back faster than it went down.
 * Checking it pops the lit cap up and draws the tick in one stroke, the way a
 * pen would; unchecking settles it back into the chassis.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import { forwardRef, useCallback, useEffect, useRef, type DOMAttributes, type MutableRefObject } from "react";
import gsap from "gsap";
import type { EchoChangeEvent, EchoInterop } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { mergeHandlers, timing, useCapPhysics, useReducedMotionRef } from "echo-ui-core/tactile";
import "./checkbox.css";

interface CheckboxOwnProps extends EchoInterop {
  checked?: boolean;
  defaultChecked?: boolean;
  indeterminate?: boolean;
  onCheckedChange?: (checked: boolean, eventDetails: EchoChangeEvent) => void;
}

/**
 * A control has to have a name: `aria-label`, or
 * `aria-labelledby` pointing at visible text. Leaving both out is a type
 * error, so it gets decided rather than forgotten.
 */
type AccessibleName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; "aria-label"?: string };

export type CheckboxProps = CheckboxOwnProps & AccessibleName;

function CheckIcon() {
  return (
    <svg className="echo-checkbox__check" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden>
      <path d="M3.5 8.5l3 3 6-7" strokeLinecap="round" strokeLinejoin="round" pathLength={1} />
    </svg>
  );
}

/**
 * Indeterminate draws a dash, not the check. Base UI shows the Indicator for
 * both states, and with one icon inside it a "some selected" parent looked
 * exactly like "all selected" — the difference existed only as aria-checked.
 */
function DashIcon() {
  return (
    <svg className="echo-checkbox__dash" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden>
      <path d="M4 8h8" strokeLinecap="round" pathLength={1} />
    </svg>
  );
}

/**
 * `forwardRef`, not a `ref` prop, and on purpose.
 *
 * On React 19 `ref` is an ordinary prop and this could be a plain function.
 * On React 18 it is not — React strips `ref` before the component runs, so
 * the same code would type-check, work on 19, and populate nothing on 18.
 * Echo supports both until a major. `forwardRef` behaves
 * identically on each.
 */
export const Checkbox = forwardRef<HTMLButtonElement, CheckboxProps>(function Checkbox(
  { onCheckedChange, ...props },
  ref,
) {
  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const root = useRef<HTMLButtonElement | null>(null);
  // A small key: no rise on hover (unchecked, it is a hole), no lean.
  const cap = useCapPhysics<HTMLElement>({ lift: 0, travel: 1.5, tilt: 0 });
  const capRef = cap.ref;

  const setRoot = useCallback(
    (node: HTMLButtonElement | null) => {
      root.current = node;
      capRef(node);
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<HTMLButtonElement | null>).current = node;
    },
    [ref, capRef],
  );

  // Space toggles a checkbox and Enter doesn't, so only Space presses it.
  const handlers: DOMAttributes<HTMLElement> = {
    ...cap.handlers,
    onKeyDown: (e) => {
      if (e.key === " ") cap.handlers.onKeyDown?.(e);
    },
    onKeyUp: (e) => {
      if (e.key === " ") cap.handlers.onKeyUp?.(e);
    },
  };

  useEffect(() => {
    const r = root.current;
    if (!r) return;
    const changed = new MutationObserver(() => {
      if (reduced.current) return;
      const on = r.hasAttribute("data-checked") || r.hasAttribute("data-indeterminate");
      gsap.fromTo(
        r,
        { scale: on ? 1.18 : 0.9 },
        { scale: 1, ...timing("rebound"), overwrite: "auto" },
      );
      if (!on) return;
      const mark = [...r.querySelectorAll<SVGPathElement>("svg path")].find(
        (p) => (p.ownerSVGElement && getComputedStyle(p.ownerSVGElement).display !== "none"),
      );
      if (mark) {
        gsap.fromTo(
          mark,
          { strokeDasharray: 1, strokeDashoffset: 1 },
          { strokeDashoffset: 0, duration: 0.26, ease: "power2.out", delay: 0.04, overwrite: "auto" },
        );
      }
    });
    changed.observe(r, { attributes: true, attributeFilter: ["data-checked", "data-unchecked", "data-indeterminate"] });
    return () => {
      changed.disconnect();
      gsap.killTweensOf(r);
    };
  }, [reduced]);

  return (
    <BaseCheckbox.Root
      ref={setRoot}
      className="echo-checkbox"
      onCheckedChange={(checked, eventDetails) => {
        sound?.play("select");
        onCheckedChange?.(checked, eventDetails);
      }}
      {...props}
      // After the caller's props, merged with them: a caller's onBlur (a
      // react-hook-form `register()`) or onKeyDown runs first, then the cap's.
      {...mergeHandlers(handlers, props)}
    >
      <BaseCheckbox.Indicator className="echo-checkbox__indicator">
        <CheckIcon />
        <DashIcon />
      </BaseCheckbox.Indicator>
    </BaseCheckbox.Root>
  );
});
